window.docContents[142].resolve({"/1___-Introduction/Acknowledgments/#Chapter1___Acknowledgments":{"contents":"This book arose from the lecture notes of a representation theory course given by the first author to the remaining six authors in March 2004 within the framework of the Clay Mathematics Institute Research Academy for high school students and its extended version given by the first author to MIT undergraduate mathematics students in the fall of 2008.\n\nThe authors are grateful to the Clay Mathematics Institute for hosting the first version of this course. The first author is very indebted to Victor Ostrik for helping him prepare this course and thanks Josh Nichols-Barrer and Thomas Lam for helping run the course in 2004 and for useful comments. He is also very grateful to Darij Grinberg for his very careful reading of the text, for many useful comments and corrections, and for suggesting Problems 2.11.6, 3.3.3, 3.8.3, 3.8.4, 4.5.2, 5.10.2 and Exercises 5.27.2, 5.27.3, 7.9.8, and to Bjorn Poonen, who taught a course based on this book and provided many useful comments and corrections. Finally, the authors gratefully acknowledge the use of the Dynkin diagram pictures prepared by W. Casselman.\n\n\n","context":"Introduction to Representation Theory\t1. Introduction\tAcknowledgments","header":"Acknowledgments","id":"/1___-Introduction/Acknowledgments/#Chapter1___Acknowledgments"},"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Quiver/#Chapter2___Definition2___8___1":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.8. Quivers\tQuiver","header":"Quiver","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Quiver/#Chapter2___Definition2___8___1"},"/5___-Representations-of-finite-groups___-Further-results/5___26___-Artin___s-theorem/#chapter-05___section-5-26":{"contents":"\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results","header":"5.26. Artin's theorem","id":"/5___-Representations-of-finite-groups___-Further-results/5___26___-Artin___s-theorem/#chapter-05___section-5-26"},"/8___-Homological-algebra/8___1___-Projective-and-injective-modules/Lifting-homomorphisms-through-extensions/#Chapter8___Exercise8___1___4":{"contents":"Exercise 8.1.4. Let A be a ring, let M_1, M_2 be left A-modules, let P_1, P_2 be projective left A-modules, and let f_i : P_i \\to M_i be homomorphisms. Let M be a left A-module containing M_1 such that M/M_1 = M_2. Show that there exists a homomorphism f : P_1 \\oplus P_2 \\to M such that f|_{P_1} = f_1 and the induced homomorphism P_2 \\to M_2 is f_2.\n\n\n\n","context":"Introduction to Representation Theory\t8. Homological algebra\t8.1. Projective and injective modules\tLifting homomorphisms through extensions","header":"Lifting homomorphisms through extensions","id":"/8___-Homological-algebra/8___1___-Projective-and-injective-modules/Lifting-homomorphisms-through-extensions/#Chapter8___Exercise8___1___4"}});
